@startuml

class Library {
  + Name : string
}

class User {
  + Name : string
  + ContactInfo : string
  + SecurityDeposit : float
}

class BorrowableItem {
  + LibraryCode : string
  + Location : string
}

class Book extends BorrowableItem {
  + Publisher : string
}

class MagazineIssue extends BorrowableItem {
  + PublicationDate : date
  + Publisher : string
}

class MusicCD extends BorrowableItem {
  + Publisher : string
  + Artist : string
}

class Film extends BorrowableItem {
  + Duration : int
  + Publisher : string
}

class DVDFilm extends Film {}

class VHSFilm extends Film {}

class Author {
  + Name : string
}

class Actor {
  + Name : string
}

class Loan {
  + ReturnDeadline : date
}

class Request {
  + RequestDate : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "0..1" -- "*" Request : receives

User "0..1" -- "*" Loan : borrows
Loan "1" -- "1" BorrowableItem : involves

Book "1" -- "1..*" Author : written by
Film "1" -- "1..*" Actor : features

@enduml

